from pathlib import Path

import pytest


def first_readable(names: list[str]) -> str:
    """Return the text of the first file in names that can be read from 'notes'.

    Names are untrusted and must resolve strictly within the 'notes' directory
    (relative to the current working directory), including subdirectories.
    If a file is missing, unreadable, or points outside 'notes', it is skipped.
    Returns an empty string if no file can be successfully read.
    """
    base = Path("notes").resolve()
    if not base.is_dir():
        return ""
    for name in names:
        try:
            candidate = (base / name).resolve()
            candidate.relative_to(base)
            if candidate == base:
                continue
            if candidate.is_file():
                return candidate.read_text(encoding="utf-8")
        except (ValueError, OSError):
            continue
    return ""


@pytest.fixture
def notes_env(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    monkeypatch.chdir(tmp_path)
    notes_dir = tmp_path / "notes"
    notes_dir.mkdir()
    return notes_dir


def test_empty_names(notes_env: Path) -> None:
    assert first_readable([]) == ""


def test_read_single_file(notes_env: Path) -> None:
    (notes_env / "hello.txt").write_text("hello world", encoding="utf-8")
    assert first_readable(["hello.txt"]) == "hello world"


def test_read_nested_file(notes_env: Path) -> None:
    sub = notes_env / "sub"
    sub.mkdir()
    (sub / "b.txt").write_text("nested content", encoding="utf-8")
    assert first_readable(["sub/b.txt"]) == "nested content"


def test_fallback_to_second_readable(notes_env: Path) -> None:
    (notes_env / "second.txt").write_text("found me", encoding="utf-8")
    assert first_readable(["missing.txt", "second.txt"]) == "found me"


def test_all_missing(notes_env: Path) -> None:
    assert first_readable(["missing1.txt", "missing2.txt"]) == ""


def test_path_traversal_parent_dir(notes_env: Path) -> None:
    outside = notes_env.parent / "secret.txt"
    outside.write_text("secret", encoding="utf-8")
    assert first_readable(["../secret.txt"]) == ""
    assert first_readable(["sub/../../secret.txt"]) == ""


def test_path_traversal_absolute(notes_env: Path) -> None:
    outside = notes_env.parent / "secret.txt"
    outside.write_text("secret", encoding="utf-8")
    assert first_readable([str(outside.resolve())]) == ""


def test_directory_target(notes_env: Path) -> None:
    sub = notes_env / "sub"
    sub.mkdir()
    assert first_readable(["sub"]) == ""


def test_symlink_escape(notes_env: Path) -> None:
    outside = notes_env.parent / "outside.txt"
    outside.write_text("outside", encoding="utf-8")
    link = notes_env / "leak.txt"
    try:
        link.symlink_to(outside)
    except OSError:
        pytest.skip("Symlinks not supported in this environment")
    assert first_readable(["leak.txt"]) == ""

